export const DailyDiamondStatement: React.FC = () => {
  const [statementDate, setStatementDate] = useState('2026-08-04');
  const [searchQuery, setSearchQuery] = useState('');
  const [filterMode, setFilterMode] = useState<'all' | 'gains' | 'consumed' | 'high_value'>('all');

  // Compute filtered rows
  const filteredData = useMemo(() => {
    return AUG_4_STATEMENT_DATA.filter((row) => {
      const sizeStr = row.size.toFixed(2);
      const matchesSearch = !searchQuery || sizeStr.includes(searchQuery) || row.costPerCt.toString().includes(searchQuery);
      const netCt = row.incomingCt - row.usedCt;

      if (!matchesSearch) return false;
      if (filterMode === 'gains') return netCt > 0;
      if (filterMode === 'consumed') return netCt < 0;
      if (filterMode === 'high_value') return row.totalValueUsd >= 5000;
      return true;
    });
  }, [searchQuery, filterMode]);

  // Overall totals
  const totals = useMemo(() => {
    return AUG_4_STATEMENT_DATA.reduce(
      (acc, r) => {
        acc.pcs += r.quantityPcs;
        acc.weight += r.weightCt;
        acc.value += r.totalValueUsd;
        acc.incoming += r.incomingCt;
        acc.used += r.usedCt;
        return acc;
      },
      { pcs: 0, weight: 0, value: 0, incoming: 0, used: 0 }
    );
  }, []);

  // Net movement
  const netMovementTotal = totals.incoming - totals.used;

  // Export to Excel CSV
  const handleExportExcel = () => {
    const headers = ['Size (mm)', 'Cost/ct (USD)', 'Quantity (pcs)', 'Weight (ct)', 'Total Value (USD)', 'IN due 8/4/2026 (ct)', 'USED due 8/4/2026 (ct)', 'Net Movement (ct)'];
    const rows = AUG_4_STATEMENT_DATA.map(r => [
      r.size.toFixed(2),
      r.costPerCt,
      r.quantityPcs,
      r.weightCt.toFixed(4),
      r.totalValueUsd.toFixed(2),
      r.incomingCt.toFixed(4),
      r.usedCt.toFixed(4),
      (r.incomingCt - r.usedCt).toFixed(4)
    ]);

    const summaryRow = ['TOTALS', '', totals.pcs, totals.weight.toFixed(4), totals.value.toFixed(2), totals.incoming.toFixed(4), totals.used.toFixed(4), netMovementTotal.toFixed(4)];

    const csvContent = 'data:text/csv;charset=utf-8,' 
      + ['KILANI DIAMOND REPORTER - DAILY DIAMOND STATEMENT', `Date: ${statementDate}`, '']
          .concat([headers.join(',')])
          .concat(rows.map(e => e.join(',')))
          .concat([''])
          .concat([summaryRow.join(',')])
          .join('\n');

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `Kilani_Diamond_Statement_${statementDate}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Print function
  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      {/* --- Top Action Header --- */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-zinc-900/60 p-6 rounded-2xl border border-zinc-800/80 backdrop-blur-md">
        <div>
          <div className="flex items-center gap-2 text-lux-gold text-xs font-bold uppercase tracking-wider mb-1">
            <Activity size={14} /> Executive Daily Snapshot
          </div>
          <h2 className="text-2xl font-bold text-white tracking-tight">Daily Diamond Statement</h2>
          <p className="text-zinc-400 text-xs mt-0.5">
            Real-time statement of active diamond inventory, factory incoming & factory consumption.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="flex items-center gap-2 bg-zinc-950 border border-zinc-800 px-3 py-2 rounded-xl">
            <Calendar size={14} className="text-lux-gold" />
            <input
              type="date"
              value={statementDate}
              onChange={(e) => setStatementDate(e.target.value)}
              className="bg-transparent text-white text-xs font-semibold focus:outline-none"
            />
          </div>

          <Button
            onClick={handleExportExcel}
            className="bg-lux-gold hover:bg-amber-500 text-black font-bold text-xs px-4 py-2.5 rounded-xl flex items-center gap-2 shadow-lg shadow-amber-500/10 transition-all"
          >
            <Download size={14} /> Export as Excel
          </Button>

          <Button
            onClick={handlePrint}
            variant="outline"
            className="border-zinc-700 hover:border-zinc-500 text-zinc-300 text-xs px-3.5 py-2.5 rounded-xl flex items-center gap-2"
          >
            <Printer size={14} /> Print
          </Button>
        </div>
      </div>

      {/* --- Hero Valuation Card --- */}
      <div className="relative overflow-hidden rounded-2xl bg-gradient-to-r from-zinc-900 via-slate-900 to-zinc-950 border border-amber-500/20 p-8 shadow-2xl">
        <div className="absolute top-0 right-0 w-96 h-96 bg-amber-500/5 rounded-full blur-3xl pointer-events-none" />

        <div className="relative z-10 flex flex-col md:flex-row md:items-end justify-between gap-6">
          <div>
            <div className="text-xs font-bold uppercase tracking-widest text-amber-400/90 mb-2 flex items-center gap-2">
              <Gem size={14} /> Statement Total Inventory Value
            </div>
            <div className="text-4xl md:text-5xl font-black text-white tracking-tight">
              ${totals.value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            </div>
            <div className="text-zinc-400 text-sm mt-2 flex items-center gap-3">
              <span className="font-semibold text-zinc-200">{totals.pcs.toLocaleString()} pcs</span>
              <span className="text-zinc-600">•</span>
              <span className="font-semibold text-zinc-200">{totals.weight.toFixed(3)} ct total weight</span>
              <span className="text-zinc-600">•</span>
              <span className="text-amber-400/80 font-medium">43 Diamond Sizes Tracked</span>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-1.5">
              <TrendingUp size={14} /> +4.2% vs previous statement
            </div>
          </div>
        </div>
      </div>

      {/* --- 4 Key Performance Metric Cards --- */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-5 bg-zinc-900/80 border-zinc-800 hover:border-zinc-700 transition-colors">
          <div className="text-[11px] font-bold uppercase tracking-wider text-zinc-400 mb-2">Total Pieces</div>
          <div className="text-3xl font-extrabold text-white">{totals.pcs.toLocaleString()}</div>
          <div className="text-xs text-zinc-500 mt-1">pcs in physical stock</div>
        </Card>

        <Card className="p-5 bg-zinc-900/80 border-zinc-800 hover:border-zinc-700 transition-colors">
          <div className="text-[11px] font-bold uppercase tracking-wider text-zinc-400 mb-2">Total Weight</div>
          <div className="text-3xl font-extrabold text-white">{totals.weight.toFixed(3)} <span className="text-lg font-bold text-zinc-400">ct</span></div>
          <div className="text-xs text-zinc-500 mt-1">across all sizes</div>
        </Card>

        <Card className="p-5 bg-cyan-950/20 border-cyan-500/30 hover:border-cyan-500/50 transition-colors">
          <div className="text-[11px] font-bold uppercase tracking-wider text-cyan-400 mb-2 flex items-center justify-between">
            <span>Incoming Today</span>
            <ArrowDownLeft size={16} className="text-cyan-400" />
          </div>
          <div className="text-3xl font-extrabold text-cyan-300">{totals.incoming.toFixed(3)} <span className="text-lg font-bold text-cyan-500">ct</span></div>
          <div className="text-xs text-cyan-400/70 mt-1">received to factory</div>
        </Card>

        <Card className="p-5 bg-amber-950/20 border-amber-500/30 hover:border-amber-500/50 transition-colors">
          <div className="text-[11px] font-bold uppercase tracking-wider text-amber-400 mb-2 flex items-center justify-between">
            <span>Factory Used</span>
            <ArrowUpRight size={16} className="text-amber-400" />
          </div>
          <div className="text-3xl font-extrabold text-amber-300">{totals.used.toFixed(4)} <span className="text-lg font-bold text-amber-500">ct</span></div>
          <div className="text-xs text-amber-400/70 mt-1">consumed in production</div>
        </Card>
      </div>

      {/* --- Filter & Search Control Bar --- */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-4 bg-zinc-900/40 p-4 rounded-xl border border-zinc-800">
        <div className="relative w-full md:w-80">
          <Search size={14} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-zinc-400" />
          <input
            type="text"
            placeholder="Search by size (e.g. 0.8, 1.4)..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-zinc-950 border border-zinc-800 text-white placeholder:text-zinc-600 text-xs rounded-xl pl-9 pr-4 py-2.5 focus:outline-none focus:border-lux-gold"
          />
        </div>

        <div className="flex flex-wrap items-center gap-2 w-full md:w-auto">
          <span className="text-xs font-semibold text-zinc-400 flex items-center gap-1 mr-1">
            <Filter size={12} /> Filter:
          </span>

          <button
            onClick={() => setFilterMode('all')}
            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
              filterMode === 'all' ? 'bg-lux-gold text-black' : 'bg-zinc-800 text-zinc-300 hover:bg-zinc-700'
            }`}
          >
            All ({AUG_4_STATEMENT_DATA.length})
          </button>

          <button
            onClick={() => setFilterMode('gains')}
            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
              filterMode === 'gains' ? 'bg-emerald-500 text-black' : 'bg-zinc-800 text-emerald-400 hover:bg-zinc-700'
            }`}
          >
            Net Incoming (+)
          </button>

          <button
            onClick={() => setFilterMode('consumed')}
            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
              filterMode === 'consumed' ? 'bg-rose-500 text-white' : 'bg-zinc-800 text-rose-400 hover:bg-zinc-700'
            }`}
          >
            Net Consumed (-)
          </button>

          <button
            onClick={() => setFilterMode('high_value')}
            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
              filterMode === 'high_value' ? 'bg-amber-400 text-black' : 'bg-zinc-800 text-amber-300 hover:bg-zinc-700'
            }`}
          >
            High Value (&gt;$5k)
          </button>
        </div>
      </div>

      {/* --- Main Detailed Inventory Statement Table --- */}
      <Card className="overflow-hidden border-zinc-800 bg-zinc-950/80 shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="bg-zinc-900/90 text-lux-gold font-bold uppercase tracking-wider text-[10px] border-b border-zinc-800">
                <th className="py-3.5 px-4">Size (mm)</th>
                <th className="py-3.5 px-4 text-right">Cost/ct (USD)</th>
                <th className="py-3.5 px-4 text-right">Quantity (pcs)</th>
                <th className="py-3.5 px-4 text-right">Weight (ct)</th>
                <th className="py-3.5 px-4 text-right">Total Value (USD)</th>
                <th className="py-3.5 px-4 text-right text-cyan-400">IN (ct)</th>
                <th className="py-3.5 px-4 text-right text-amber-400">USED (ct)</th>
                <th className="py-3.5 px-4 text-right">Net Movement</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-800/60 font-mono">
              {filteredData.map((row) => {
                const netCt = row.incomingCt - row.usedCt;
                const isNetPositive = netCt > 0;
                const isNetNegative = netCt < 0;

                return (
                  <tr key={row.size} className="hover:bg-zinc-900/50 transition-colors">
                    <td className="py-3 px-4 font-bold text-white font-sans">{row.size.toFixed(2)} mm</td>
                    <td className="py-3 px-4 text-right text-zinc-300">${row.costPerCt.toLocaleString()}</td>
                    <td className="py-3 px-4 text-right text-zinc-200">{row.quantityPcs.toLocaleString()}</td>
                    <td className="py-3 px-4 text-right text-zinc-200 font-bold">{row.weightCt.toFixed(3)} ct</td>
                    <td className="py-3 px-4 text-right font-bold text-amber-300">
                      ${row.totalValueUsd.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </td>
                    <td className="py-3 px-4 text-right text-cyan-400 font-semibold">{row.incomingCt.toFixed(3)}</td>
                    <td className="py-3 px-4 text-right text-amber-400 font-semibold">{row.usedCt.toFixed(4)}</td>
                    <td className="py-3 px-4 text-right">
                      {isNetPositive && (
                        <span className="inline-flex items-center gap-1 font-bold text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded">
                          +{netCt.toFixed(3)} ct
                        </span>
                      )}
                      {isNetNegative && (
                        <span className="inline-flex items-center gap-1 font-bold text-rose-400 bg-rose-500/10 px-2 py-0.5 rounded">
                          {netCt.toFixed(3)} ct
                        </span>
                      )}
                      {!isNetPositive && !isNetNegative && (
                        <span className="text-zinc-600">0.000 ct</span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot>
              <tr className="bg-zinc-900 text-white font-bold border-t-2 border-lux-gold/60 text-xs">
                <td className="py-4 px-4 font-sans text-lux-gold">STATEMENT TOTALS ({filteredData.length} sizes)</td>
                <td className="py-4 px-4 text-right">--</td>
                <td className="py-4 px-4 text-right font-mono">{totals.pcs.toLocaleString()}</td>
                <td className="py-4 px-4 text-right font-mono text-lux-gold">{totals.weight.toFixed(3)} ct</td>
                <td className="py-4 px-4 text-right font-mono text-amber-300">
                  ${totals.value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </td>
                <td className="py-4 px-4 text-right font-mono text-cyan-400">{totals.incoming.toFixed(3)} ct</td>
                <td className="py-4 px-4 text-right font-mono text-amber-400">{totals.used.toFixed(4)} ct</td>
                <td className="py-4 px-4 text-right font-mono">
                  <span className={netMovementTotal >= 0 ? 'text-emerald-400' : 'text-rose-400'}>
                    {netMovementTotal >= 0 ? '+' : ''}{netMovementTotal.toFixed(3)} ct
                  </span>
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </Card>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Download, Printer, Search, ArrowDownLeft, ArrowUpRight, Filter, Calendar, Activity, Gem, TrendingUp } from 'lucide-react';
import { Card, Button } from '../UI';

export interface DailyStatementRow {
  size: number;
  costPerCt: number;
  quantityPcs: number;
  weightCt: number;
  totalValueUsd: number;
  incomingCt: number;
  usedCt: number;
}

export const AUG_4_STATEMENT_DATA: DailyStatementRow[] = [
  { size: 0.50, costPerCt: 750, quantityPcs: 701, weightCt: 0.645, totalValueUsd: 483.75, incomingCt: 0, usedCt: 0.104 },
  { size: 0.60, costPerCt: 750, quantityPcs: 1326, weightCt: 1.591, totalValueUsd: 1193.25, incomingCt: 0, usedCt: 0.7252 },
