export const DailyDiamondStatement: React.FC = () => {
  const [statementDate, setStatementDate] = useState('2026-08-04');
  const [searchQuery, setSearchQuery] = useState('');
  const [filterMode, setFilterMode] = useState<'all' | 'gains' | 'consumed' | 'high_value'>('all');

  const filteredData = useMemo(() => {
    return AUG_4_STATEMENT_DATA.filter((row) => {
      const sizeStr = row.size.toFixed(2);
      const matchesSearch = !searchQuery || sizeStr.includes(searchQuery) || row.costPerCt.toString().includes(searchQuery);
      const netCt = row.incomingCt - row.usedCt;

      if (!matchesSearch) return false;
      if (filterMode === 'gains') return netCt > 0;
      if (filterMode === 'consumed') return netCt < 0;
      if (filterMode === 'high_value') return row.totalValueUsd >= 5000;
      return true;
    });
  }, [searchQuery, filterMode]);

  const totals = useMemo(() => {
    return AUG_4_STATEMENT_DATA.reduce(
      (acc, r) => {
        acc.pcs += r.quantityPcs;
        acc.weight += r.weightCt;
        acc.value += r.totalValueUsd;
        acc.incoming += r.incomingCt;
        acc.used += r.usedCt;
        return acc;
      },
      { pcs: 0, weight: 0, value: 0, incoming: 0, used: 0 }
    );
  }, []);

  const netMovementTotal = totals.incoming - totals.used;

  const handleExportExcel = () => {
    const headers = ['Size (mm)', 'Cost/ct (USD)', 'Quantity (pcs)', 'Weight (ct)', 'Total Value (USD)', 'IN due 8/4/2026 (ct)', 'USED due 8/4/2026 (ct)', 'Net Movement (ct)'];
    const rows = AUG_4_STATEMENT_DATA.map(r => [
      r.size.toFixed(2),
      r.costPerCt,
      r.quantityPcs,
      r.weightCt.toFixed(4),
      r.totalValueUsd.toFixed(2),
      r.incomingCt.toFixed(4),
      r.usedCt.toFixed(4),
      (r.incomingCt - r.usedCt).toFixed(4)
    ]);

    const summaryRow = ['TOTALS', '', totals.pcs, totals.weight.toFixed(4), totals.value.toFixed(2), totals.incoming.toFixed(4), totals.used.toFixed(4), netMovementTotal.toFixed(4)];

    const csvContent = 'data:text/csv;charset=utf-8,' 
      + ['KILANI DIAMOND REPORTER - DAILY DIAMOND STATEMENT', `Date: ${statementDate}`, '']
          .concat([headers.join(',')])
          .concat(rows.map(e => e.join(',')))
          .concat([''])
          .concat([summaryRow.join(',')])
          .join('\n');

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `Kilani_Diamond_Statement_${statementDate}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      {/* Top Action Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-zinc-900/60 p-6 rounded-2xl border border-zinc-800/80 backdrop-blur-md">
        <div>
          <div className="flex items-center gap-2 text-lux-gold text-xs font-bold uppercase tracking-wider mb-1">
            <Activity size={14} /> Executive Daily Snapshot
          </div>
          <h2 className="text-2xl font-bold text-white tracking-tight">Daily Diamond Statement</h2>
          <p className="text-zinc-400 text-xs mt-0.5">
            Real-time statement of active diamond inventory, factory incoming & factory consumption.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="flex items-center gap-2 bg-zinc-950 border border-zinc-800 px-3 py-2 rounded-xl">
            <Calendar size={14} className="text-lux-gold" />
            <input
              type="date"
              value={statementDate}
              onChange={(e) => setStatementDate(e.target.value)}
              className="bg-transparent text-white text-xs font-semibold focus:outline-none"
            />
          </div>

          <Button
            onClick={handleExportExcel}
            className="bg-lux-gold hover:bg-amber-500 text-black font-bold text-xs px-4 py-2.5 rounded-xl flex items-center gap-2 shadow-lg shadow-amber-500/10 transition-all"
          >
            <Download size={14} /> Export as Excel
          </Button>

          <Button
            onClick={handlePrint}
            variant="outline"
            className="border-zinc-700 hover:border-zinc-500 text-zinc-300 text-xs px-3.5 py-2.5 rounded-xl flex items-center gap-2"
          >
            <Printer size={14} /> Print
          </Button>
        </div>
      </div>

      {/* Hero Valuation Card */}
      <div className="relative overflow-hidden rounded-2xl bg-gradient-to-r from-zinc-900 via-slate-900 to-zinc-950 border border-amber-500/20 p-8 shadow-2xl">
        <div className="absolute top-0 right-0 w-96 h-96 bg-amber-500/5 rounded-full blur-3xl pointer-events-none" />

        <div className="relative z-10 flex flex-col md:flex-row md:items-end justify-between gap-6">
          <div>
            <div className="text-xs font-bold uppercase tracking-widest text-amber-400/90 mb-2 flex items-center gap-2">
              <Gem size={14} /> Statement Total Inventory Value
            </div>
            <div className="text-4xl md:text-5xl font-black text-white tracking-tight">
              ${totals.value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            </div>
            <div className="text-zinc-400 text-sm mt-2 flex items-center gap-3">
              <span className="font-semibold text-zinc-200">{totals.pcs.toLocaleString()} pcs</span>
              <span className="text-zinc-600">•</span>
              <span className="font-semibold text-zinc-200">{totals.weight.toFixed(3)} ct total weight</span>
              <span className="text-zinc-600">•</span>
              <span className="text-amber-400/80 font-medium">43 Diamond Sizes Tracked</span>
            </div>
          </div>

          <div className="flex items-center gap-3">
