    switch (shape) {
      case 'Princess': return '🔳';
      case 'Emerald': return '📐';
      case 'Oval': return '🥚';
      case 'Cushion': return '🔲';
      case 'Marquise': return '💧';
      default: return '💎';
    }
  };

