            className="rounded-[32px] p-8 relative overflow-hidden bg-gradient-to-b from-[#111625] to-[#0a0d16] border border-amber-500/20 shadow-[0_20px_40px_-15px_rgba(245,158,11,0.15)] group hover:border-amber-500/40 transition-all duration-500"
          >
