            <div className="absolute top-0 right-0 p-8">
              <div className="w-12 h-12 rounded-full bg-amber-500/10 border border-amber-500/20 flex items-center justify-center">
                <Activity className="w-5 h-5 text-amber-400" />
              </div>
            </div>
            <div className="relative z-10 h-full flex flex-col justify-end mt-16">
              <div className="text-amber-500/70 text-[11px] font-black uppercase tracking-[0.25em] mb-3">Inventory Total Value</div>
              <div className="text-4xl lg:text-5xl font-black text-white tabular-nums tracking-tighter mb-2" style={{ textShadow: '0 4px 20px rgba(0,0,0,0.5)' }}>
                ${totalValueUsd.toLocaleString(undefined, { maximumFractionDigits: 0 })}
              </div>
              <div className="text-zinc-400 text-sm font-semibold">USD Valuation</div>
            </div>
          </motion.div>

          {/* Widget 2: Coming In (Neon Green Glow) */}
          <motion.div 
            initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}
            className="rounded-[32px] p-8 relative overflow-hidden bg-gradient-to-b from-[#0f1f18] to-[#0a110e] border border-emerald-500/20 shadow-[0_20px_40px_-15px_rgba(16,185,129,0.15)] group hover:border-emerald-500/40 transition-all duration-500"
          >
            <div className="absolute -inset-[100%] bg-[radial-gradient(circle_at_50%_100%,rgba(16,185,129,0.15),transparent_60%)] opacity-50 group-hover:opacity-100 transition-opacity duration-700" />
            <div className="absolute top-0 right-0 p-8">
              <div className="w-12 h-12 rounded-full bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
                <ArrowDownLeft className="w-5 h-5 text-emerald-400" />
              </div>
            </div>
            <div className="relative z-10 h-full flex flex-col justify-end mt-16">
              <div className="text-emerald-500/70 text-[11px] font-black uppercase tracking-[0.25em] mb-3">Total Diamonds Incoming</div>
              <div className="text-4xl lg:text-5xl font-black text-emerald-400 tabular-nums tracking-tighter mb-2 drop-shadow-[0_0_15px_rgba(16,185,129,0.3)]">
                +{incomingCt.toLocaleString(undefined, { maximumFractionDigits: 2 })}
              </div>
              <div className="text-zinc-400 text-sm font-semibold">{incomingPcs.toLocaleString()} Pieces Received</div>
            </div>
          </motion.div>

          {/* Widget 3: Overview (Purple/Orange Gradient) */}
          <motion.div 
            initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}
            className="rounded-[32px] p-8 relative overflow-hidden bg-gradient-to-b from-[#181125] to-[#0e0a16] border border-purple-500/20 shadow-[0_20px_40px_-15px_rgba(168,85,247,0.15)] group flex flex-col justify-between hover:border-purple-500/40 transition-all duration-500"
          >
            <div className="absolute -inset-[100%] bg-[radial-gradient(circle_at_50%_0%,rgba(168,85,247,0.15),transparent_40%),radial-gradient(circle_at_50%_100%,rgba(249,115,22,0.15),transparent_40%)] opacity-60 group-hover:opacity-100 transition-opacity duration-700" />

            <div className="relative z-10">
              <div className="w-12 h-12 rounded-full bg-purple-500/10 border border-purple-500/20 flex items-center justify-center mb-6">
                <Layers className="w-5 h-5 text-purple-400" />
              </div>
            </div>

            <div className="relative z-10 flex justify-between items-end bg-black/20 p-5 rounded-2xl border border-white/5 backdrop-blur-md">
              <div>
                <div className="text-zinc-400 text-[10px] font-black uppercase tracking-[0.2em] mb-1">Total Pieces</div>
                <div className="text-2xl font-bold text-white tabular-nums">{totalPcs.toLocaleString()}</div>
              </div>
              <div className="w-px h-8 bg-zinc-800" />
              <div className="text-right">
                <div className="text-zinc-400 text-[10px] font-black uppercase tracking-[0.2em] mb-1">Total Weight</div>
                <div className="text-2xl font-bold text-white tabular-nums">{totalCt.toLocaleString(undefined, {maximumFractionDigits: 2})} ct</div>
              </div>
            </div>
          </motion.div>
        </div>

        {/* ── SPLIT WIDGET: FACTORY MOVEMENT ──────────────────────── */}
        <motion.div 
          initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}
          className="rounded-[32px] relative overflow-hidden bg-[#0d1220] border border-zinc-800/80 shadow-2xl flex flex-col md:flex-row group"
        >
          {/* Sent to Factory Half */}
          <div className="flex-1 p-8 border-b md:border-b-0 md:border-r border-zinc-800/80 hover:bg-cyan-500/5 transition-colors cursor-pointer relative overflow-hidden">
             <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_left,rgba(6,182,212,0.08),transparent_50%)] opacity-0 group-hover:opacity-100 transition-opacity" />
             <div className="relative z-10">
                <div className="flex items-center gap-2 text-cyan-400/80 text-[10px] font-black uppercase tracking-[0.25em] mb-4">
                  <Factory className="w-4 h-4" /> Sent to Factory
                </div>
                <div className="text-4xl font-black text-white tabular-nums tracking-tight mb-2 drop-shadow-lg">{sentToFactoryCt.toFixed(2)} ct</div>
                <div className="text-zinc-500 text-sm font-semibold transition-colors group-hover:text-cyan-400/80">{sentToFactoryPcs.toLocaleString()} Pieces Issued</div>
             </div>
          </div>

          {/* Used in Factory Half */}
          <div className="flex-1 p-8 hover:bg-amber-500/5 transition-colors cursor-pointer relative overflow-hidden">
             <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,rgba(245,158,11,0.08),transparent_50%)] opacity-0 group-hover:opacity-100 transition-opacity" />
             <div className="relative z-10">
                <div className="flex items-center justify-end gap-2 text-amber-500/80 text-[10px] font-black uppercase tracking-[0.25em] mb-4">
                  <ArrowUpRight className="w-4 h-4" /> Used in Factory
                </div>
                <div className="text-4xl font-black text-white tabular-nums tracking-tight mb-2 text-right drop-shadow-lg">{usedCt.toFixed(2)} ct</div>
                <div className="text-zinc-500 text-sm font-semibold transition-colors group-hover:text-amber-400/80 text-right">{usedPcs.toLocaleString()} Pieces Setted</div>
             </div>
          </div>
        </motion.div>

        {/* ── LEDGER & FILTERS ────────────────────────────── */}
        <div className="bg-[#0d1220] rounded-[32px] border border-zinc-800/80 p-6 shadow-2xl">
          <div className="flex flex-col md:flex-row items-center justify-between gap-4 mb-8">

            {/* Filter Pills */}
            <div className="flex items-center gap-2 bg-zinc-900/50 p-1.5 rounded-2xl border border-zinc-800/50 w-full md:w-auto overflow-x-auto">
              {[
                { id: 'SHIPMENT_IN', label: 'Shipment In' },
                { id: 'OUTGOING', label: 'Outgoing' },
                { id: 'SETTED', label: 'Setted' }
              ].map(filter => (
                <button
                  key={filter.id}
                  onClick={() => setFilterMode(filter.id as any)}
                  className={`px-5 py-2.5 rounded-xl text-sm font-bold whitespace-nowrap transition-all ${
                    filterMode === filter.id 
                    ? 'bg-zinc-800 text-white shadow-lg' 
                    : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800/50'
                  }`}
                >
                  {filter.label}
                </button>
              ))}
            </div>

            {/* Search */}
            <div className="relative w-full md:w-72">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
              <input
                type="text"
                placeholder="Search ID, source..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-zinc-900/50 border border-zinc-800/80 rounded-2xl pl-11 pr-4 py-3 text-sm text-white placeholder-zinc-500 focus:outline-none focus:border-amber-500/50 transition-colors"
              />
            </div>
          </div>

          {/* List View */}
          <div className="space-y-3 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
            <AnimatePresence mode="popLayout">
              {ledgerItems.length === 0 ? (
                <motion.div 
                  initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                  className="py-12 text-center text-zinc-500 text-sm font-medium"
                >
                  No records found for this filter.
                </motion.div>
              ) : (
                ledgerItems.map((item, i) => (
                  <motion.div
                    key={item.id}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, scale: 0.95 }}
                    transition={{ delay: i * 0.05 }}
                    className="flex items-center justify-between p-4 rounded-2xl bg-black/20 border border-white/5 hover:bg-zinc-800/40 transition-colors"
                  >
                    <div className="flex items-center gap-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${item.bg}`}>
                        {filterMode === 'SHIPMENT_IN' && <ArrowDownLeft className={`w-5 h-5 ${item.color}`} />}
                        {filterMode === 'OUTGOING' && <Factory className={`w-5 h-5 ${item.color}`} />}
                        {filterMode === 'SETTED' && <ArrowUpRight className={`w-5 h-5 ${item.color}`} />}
                      </div>
                      <div>
                        <div className="text-white font-bold text-sm">{item.title}</div>
                        <div className="text-zinc-500 text-xs font-medium mt-0.5">{item.ref} · {new Date(item.date).toLocaleDateString()}</div>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-white font-black tabular-nums">{item.ct.toFixed(3)} ct</div>
                      <div className="text-zinc-500 text-xs font-medium mt-0.5">{item.pcs.toLocaleString()} pcs</div>
                    </div>
                  </motion.div>
                ))
              )}
            </AnimatePresence>
          </div>
        </div>

      </div>
    </div>
  );
};

