import React, { useState, useMemo, useEffect } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { store } from '../../services/store';
import { InventoryMovementType, ProjectStatus, DiamondSpec, InventoryMovement, Project } from '../../types';
import { 
  Search, Calendar, Activity, Gem, Diamond, Factory, ArrowDownLeft, 
  ArrowUpRight, Clock, Layers, Download, Printer, Filter, Sparkles, ChevronRight
} from 'lucide-react';

export const DailyDiamondStatement: React.FC = () => {
  const [filterMode, setFilterMode] = useState<'SHIPMENT_IN' | 'OUTGOING' | 'SETTED'>('SHIPMENT_IN');
  const [searchQuery, setSearchQuery] = useState('');
  const [statementDate, setStatementDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [activeTab, setActiveTab] = useState<'melees' | 'big_stones'>('melees');

  // Real Data Integration using Store subscription
  const [specs, setSpecs] = useState<DiamondSpec[]>(() => [...store.getSpecs()]);
  const [movements, setMovements] = useState<InventoryMovement[]>(() => [...store.getInventoryMovements()]);
  const [projects, setProjects] = useState<Project[]>(() => [...store.getProjects()]);

  useEffect(() => {
    return store.subscribe(() => {
      setSpecs([...store.getSpecs()]);
      setMovements([...store.getInventoryMovements()]);
      setProjects([...store.getProjects()]);
    });
  }, []);

  // 1. Overall Inventory Valuation & Overview
  const { totalValueUsd, totalPcs, totalCt } = useMemo(() => {
    return specs.reduce(
      (acc, s) => {
        const ct = s.ct || 0;
        const pcs = s.pcs || 0;
        const cost = s.defaultCostPerCtUsd || 0;
        acc.totalValueUsd += ct * cost;
        acc.totalPcs += pcs;
        acc.totalCt += ct;
        return acc;
      },
      { totalValueUsd: 0, totalPcs: 0, totalCt: 0 }
    );
  }, [specs]);

  // 2. Incoming Shipments
  const incomingMovements = useMemo(() => {
    return movements.filter(m => m.type === InventoryMovementType.SHIPMENT_IN);
  }, [movements]);

  const { incomingCt, incomingPcs } = useMemo(() => {
    return incomingMovements.reduce((acc, m) => {
      m.lines.forEach(l => {
        acc.incomingCt += l.ct || 0;
        acc.incomingPcs += l.pcs || 0;
      });
      return acc;
    }, { incomingCt: 0, incomingPcs: 0 });
  }, [incomingMovements]);

  // 3. Sent to Factory (Issues) & Used (Projects)
  const { usedPcs, usedCt, sentToFactoryPcs, sentToFactoryCt } = useMemo(() => {
    let usedPcsAcc = 0;
    let usedCtAcc = 0;
    let sentPcsAcc = 0;
    let sentCtAcc = 0;

    // Calculate Sent to Factory from ISSUE movements
    const issueMovements = movements.filter(m => m.type === InventoryMovementType.ISSUE);
    issueMovements.forEach(m => {
      m.lines.forEach(l => {
        sentPcsAcc += l.pcs || 0;
        sentCtAcc += l.ct || 0;
      });
    });

    // Calculate Used from Project Cost Summaries
    projects.forEach(p => {
      const summary = store.getProjectCostSummary(p.id);
      summary.breakdown.forEach(b => {
        const spec = specs.find(s => s.id === b.componentId);
        if (spec) {
           const uPcs = b.usedPcs || 0;
           usedPcsAcc += uPcs;
           usedCtAcc += uPcs * (spec.ctPerStone || 0);
        }
      });
    });

    return { usedPcs: usedPcsAcc, usedCt: usedCtAcc, sentToFactoryPcs: sentPcsAcc, sentToFactoryCt: sentCtAcc };
  }, [movements, projects, specs]);

  // Ledger Items Generation
  const ledgerItems = useMemo(() => {
    let items: any[] = [];

    if (filterMode === 'SHIPMENT_IN') {
      items = incomingMovements.map(m => ({
        id: m.id,
        date: m.createdAt,
        title: m.supplier || 'Incoming Diamond Shipment',
        ref: m.invoiceNo ? `Invoice #${m.invoiceNo}` : 'Direct Stock Intake',
        pcs: m.lines.reduce((acc, l) => acc + (l.pcs || 0), 0),
        ct: m.lines.reduce((acc, l) => acc + (l.ct || 0), 0),
        badgeText: 'Shipment In',
        badgeColor: 'bg-emerald-50 text-emerald-700 border-emerald-200/80',
        iconBg: 'bg-emerald-100 text-emerald-600',
        amountColor: 'text-emerald-700'
      }));
    } else if (filterMode === 'OUTGOING') {
      const issues = movements.filter(m => m.type === InventoryMovementType.ISSUE);
      items = issues.map(m => ({
        id: m.id,
        date: m.createdAt,
        title: 'Dispatched to Setter / Factory',
        ref: m.referenceProjectId ? `Project ${m.referenceProjectId}` : m.referenceBagNumber ? `Bag #${m.referenceBagNumber}` : 'Factory Dispatch',
        pcs: m.lines.reduce((acc, l) => acc + (l.pcs || 0), 0),
        ct: m.lines.reduce((acc, l) => acc + (l.ct || 0), 0),
        badgeText: 'Sent to Factory',
        badgeColor: 'bg-blue-50 text-blue-700 border-blue-200/80',
        iconBg: 'bg-blue-100 text-blue-600',
        amountColor: 'text-blue-700'
      }));
    } else if (filterMode === 'SETTED') {
      items = projects.filter(p => p.status === ProjectStatus.CLOSED || p.status === ProjectStatus.QC).map(p => {
        const summary = store.getProjectCostSummary(p.id);
        const uPcs = summary.breakdown.reduce((acc, b) => acc + (b.usedPcs || 0), 0);
        let uCt = 0;
        summary.breakdown.forEach(b => {
          const spec = specs.find(s => s.id === b.componentId);
          if (spec) uCt += (b.usedPcs || 0) * (spec.ctPerStone || 0);
        });
        return {
          id: p.id,
          date: p.completedAt || p.createdAt,
          title: `Project ${p.code || p.id} Completed`,
          ref: p.clientName ? `Client: ${p.clientName}` : 'Factory Assembly Completed',
          pcs: uPcs,
          ct: uCt,
          badgeText: 'Stones Setted',
          badgeColor: 'bg-amber-50 text-amber-800 border-amber-200/80',
          iconBg: 'bg-amber-100 text-amber-600',
          amountColor: 'text-amber-800'
        };
      }).filter(item => item.pcs > 0);
    }

    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      items = items.filter(i => i.title.toLowerCase().includes(q) || i.ref.toLowerCase().includes(q));
    }

    return items.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [filterMode, incomingMovements, movements, projects, specs, searchQuery]);

  const handleExportCSV = () => {
    const headers = ['ID', 'Date', 'Type', 'Title', 'Reference', 'Carats (ct)', 'Pieces (pcs)'];
    const rows = ledgerItems.map(item => [
      item.id,
      new Date(item.date).toLocaleDateString(),
      filterMode,
      `"${item.title}"`,
      `"${item.ref}"`,
      item.ct.toFixed(3),
      item.pcs
    ]);
    const csvContent = 'data:text/csv;charset=utf-8,' + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `Daily_Diamond_Statement_${filterMode}_${statementDate}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="min-h-screen bg-slate-50/70 p-4 md:p-8 font-sans text-slate-900 selection:bg-amber-500/20">
      <div className="max-w-7xl mx-auto space-y-8">

        {/* ── HEADER & NAVIGATION (LIGHT APPLE GLASS) ──────────────────────── */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">

          {/* Top Melees vs Big Stones Toggle */}
          <div className="flex bg-white/80 p-1.5 rounded-2xl border border-slate-200/80 shadow-sm backdrop-blur-xl relative overflow-hidden">
            <button 
              onClick={() => setActiveTab('melees')}
              className={`relative z-10 px-8 py-3 rounded-xl text-sm font-bold transition-all active:scale-95 ${
                activeTab === 'melees'
                  ? 'text-slate-900 bg-amber-400/90 shadow-lg shadow-amber-400/30 border border-amber-400'
                  : 'text-slate-500 hover:text-slate-900'
              }`}
            >
              <Gem className="inline-block w-4 h-4 mr-2 text-slate-900" /> MELEES
            </button>
            <button 
              disabled
              className="relative z-10 px-8 py-3 rounded-xl text-sm font-bold text-slate-400 opacity-60 cursor-not-allowed flex items-center gap-2"
            >
              <Diamond className="w-4 h-4" /> BIG STONES 
              <span className="text-[9px] font-extrabold uppercase tracking-widest bg-slate-100 text-slate-500 px-2 py-0.5 rounded-md border border-slate-200">
                Coming Soon
              </span>
            </button>
          </div>

          {/* Time & Export Controls */}
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-2.5 bg-white/90 backdrop-blur-xl border border-slate-200/80 px-4 py-2.5 rounded-2xl text-xs font-semibold text-slate-700 shadow-sm">
              <Calendar className="w-4 h-4 text-amber-500" />
              <input
                type="date"
                value={statementDate}
                onChange={(e) => setStatementDate(e.target.value)}
                className="bg-transparent text-slate-800 focus:outline-none cursor-pointer font-bold"
              />
            </div>

            <button
              onClick={handleExportCSV}
              className="bg-slate-900 hover:bg-slate-800 text-white font-bold text-xs px-5 py-2.5 rounded-2xl flex items-center gap-2 shadow-md shadow-slate-900/10 transition-transform active:scale-95"
            >
              <Download size={14} /> Export CSV
            </button>

            <button
              onClick={handlePrint}
              className="bg-white hover:bg-slate-50 text-slate-700 border border-slate-200 font-bold text-xs px-4 py-2.5 rounded-2xl flex items-center gap-2 transition-colors shadow-sm"
            >
              <Printer size={14} /> Print
            </button>
          </div>
        </div>

        {/* ── STREAMLINED EXECUTIVE APPLE CARDS (LIGHT MODE) ──────────────────────── */}
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">

          {/* Card 1: Inventory Total Value */}
          <motion.div 
            initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }}
            className="rounded-3xl p-6 bg-gradient-to-br from-amber-50/80 via-white to-amber-50/20 border border-amber-200/70 shadow-xl shadow-amber-500/5 backdrop-blur-xl relative overflow-hidden group hover:border-amber-300 transition-all duration-300"
          >
            <div className="flex items-center justify-between mb-4">
              <span className="text-[11px] font-black uppercase tracking-wider text-amber-700/90 flex items-center gap-1.5">
                <Activity className="w-3.5 h-3.5 text-amber-600" /> Inventory Total Value
              </span>
              <div className="w-9 h-9 rounded-2xl bg-amber-100/80 border border-amber-200 flex items-center justify-center shadow-sm">
                <Gem className="w-4 h-4 text-amber-600" />
              </div>
            </div>
            <div>
              <div className="text-3xl lg:text-4xl font-black text-slate-900 tabular-nums tracking-tight mb-1">
                ${totalValueUsd.toLocaleString(undefined, { maximumFractionDigits: 0 })}
              </div>
              <div className="text-slate-500 text-xs font-semibold">USD Catalog Valuation</div>
            </div>
          </motion.div>

          {/* Card 2: Total Income Today */}
          <motion.div 
            initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}
            className="rounded-3xl p-6 bg-gradient-to-br from-emerald-50/80 via-white to-emerald-50/20 border border-emerald-200/70 shadow-xl shadow-emerald-500/5 backdrop-blur-xl relative overflow-hidden group hover:border-emerald-300 transition-all duration-300"
          >
            <div className="flex items-center justify-between mb-4">
              <span className="text-[11px] font-black uppercase tracking-wider text-emerald-700/90 flex items-center gap-1.5">
                <ArrowDownLeft className="w-3.5 h-3.5 text-emerald-600" /> Total Income Today
              </span>
              <div className="w-9 h-9 rounded-2xl bg-emerald-100/80 border border-emerald-200 flex items-center justify-center shadow-sm">
                <Sparkles className="w-4 h-4 text-emerald-600" />
              </div>
            </div>
            <div>
              <div className="text-3xl lg:text-4xl font-black text-emerald-600 tabular-nums tracking-tight mb-1">
                +{incomingCt.toLocaleString(undefined, { maximumFractionDigits: 2 })} <span className="text-sm font-bold text-emerald-500">ct</span>
              </div>
              <div className="text-slate-500 text-xs font-semibold">{incomingPcs.toLocaleString()} Pieces Received</div>
            </div>
          </motion.div>

          {/* Card 3: Factory Movement (Sent vs Used) */}
          <motion.div 
            initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}
            className="rounded-3xl p-6 bg-gradient-to-br from-blue-50/80 via-white to-indigo-50/20 border border-blue-200/70 shadow-xl shadow-blue-500/5 backdrop-blur-xl relative overflow-hidden group hover:border-blue-300 transition-all duration-300 flex flex-col justify-between"
          >
            <div className="flex items-center justify-between mb-3">
              <span className="text-[11px] font-black uppercase tracking-wider text-blue-700/90 flex items-center gap-1.5">
                <Factory className="w-3.5 h-3.5 text-blue-600" /> Sent to Factory
              </span>
              <div className="w-9 h-9 rounded-2xl bg-blue-100/80 border border-blue-200 flex items-center justify-center shadow-sm">
                <Layers className="w-4 h-4 text-blue-600" />
              </div>
            </div>
            <div>
              <div className="text-3xl lg:text-4xl font-black text-blue-700 tabular-nums tracking-tight mb-1">
                {sentToFactoryCt.toFixed(2)} <span className="text-sm font-bold text-blue-500">ct</span>
              </div>
              <div className="text-slate-500 text-xs font-semibold">{sentToFactoryPcs.toLocaleString()} Pieces Dispatched</div>
            </div>
          </motion.div>

          {/* Card 4: Used in Factory */}
          <motion.div 
            initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}
            className="rounded-3xl p-6 bg-gradient-to-br from-indigo-50/80 via-white to-purple-50/20 border border-indigo-200/70 shadow-xl shadow-indigo-500/5 backdrop-blur-xl relative overflow-hidden group hover:border-indigo-300 transition-all duration-300 flex flex-col justify-between"
