              <div className="w-9 h-9 rounded-2xl bg-indigo-100/80 border border-indigo-200 flex items-center justify-center shadow-sm">
                <Activity className="w-4 h-4 text-indigo-600" />
              </div>
            </div>
            <div>
              <div className="text-3xl lg:text-4xl font-black text-indigo-700 tabular-nums tracking-tight mb-1">
