              </div>
              <div className="text-slate-500 text-xs font-semibold">{usedPcs.toLocaleString()} Pieces Setted</div>
            </div>
          </motion.div>

        </div>

        {/* ── SCANABLE MOVEMENT ACTIVITY LEDGER (LIGHT GLASS) ──────────────────────── */}
        <div className="bg-white/90 backdrop-blur-xl rounded-3xl border border-slate-200/80 p-6 md:p-8 shadow-xl shadow-slate-200/50 space-y-6">

